import java.util.*;

public class Main {
    enum SendStatus { CONFIRMED, RETURNED, UNKNOWN }
    record Message(String id, String businessKey, String routingKey, String body) {}
    record PublishOutcome(SendStatus status, boolean routed) {}

    static final class QueueBox {
        final String name;
        final Deque<Message> ready = new ArrayDeque<>();
        final Deque<Message> unacked = new ArrayDeque<>();
        QueueBox dlq;
        QueueBox(String name) { this.name = name; }
        Message deliver() {
            Message msg = ready.removeFirst();
            unacked.addLast(msg);
            return msg;
        }
        void ack(Message msg) { unacked.remove(msg); }
        void nack(Message msg, boolean requeue) {
            unacked.remove(msg);
            if (requeue) ready.addFirst(msg);
            else dlq.ready.addLast(msg);
        }
        void closeChannelAndRequeueUnacked() {
            while (!unacked.isEmpty()) ready.addFirst(unacked.removeLast());
        }
    }

    static final class Broker {
        final QueueBox orderQueue = new QueueBox("order.q");
        final QueueBox deadLetterQueue = new QueueBox("order.dlq");
        Broker() { orderQueue.dlq = deadLetterQueue; }
        PublishOutcome publish(Message msg, boolean mandatory, boolean confirmTimeout) {
            if (confirmTimeout) return new PublishOutcome(SendStatus.UNKNOWN, false);
            if (!"order.created".equals(msg.routingKey())) {
                return new PublishOutcome(mandatory ? SendStatus.RETURNED : SendStatus.CONFIRMED, false);
            }
            orderQueue.ready.addLast(msg);
            return new PublishOutcome(SendStatus.CONFIRMED, true);
        }
    }

    static final class Consumer {
        final Set<String> processedBusinessKeys = new HashSet<>();
        int applied;
        int duplicateSkipped;
        void handle(Broker broker, Message msg, boolean businessFails, boolean ackLost) {
            if (businessFails) {
                broker.orderQueue.nack(msg, false);
                return;
            }
            if (processedBusinessKeys.add(msg.businessKey())) applied++;
            else duplicateSkipped++;
            if (!ackLost) broker.orderQueue.ack(msg);
        }
    }

    public static void main(String[] args) {
        Broker broker = new Broker();
        Consumer consumer = new Consumer();

        PublishOutcome ok = broker.publish(new Message("m1", "order-1001", "order.created", "create"), true, false);
        PublishOutcome returned = broker.publish(new Message("m2", "order-404", "order.missing", "bad route"), true, false);
        PublishOutcome unknown = broker.publish(new Message("m3", "order-1002", "order.created", "timeout"), true, true);

        Message firstDelivery = broker.orderQueue.deliver();
        consumer.handle(broker, firstDelivery, false, true);
        broker.orderQueue.closeChannelAndRequeueUnacked();
        Message redelivery = broker.orderQueue.deliver();
        consumer.handle(broker, redelivery, false, false);

        broker.publish(new Message("m4", "order-1003", "order.created", "poison"), true, false);
        Message poison = broker.orderQueue.deliver();
        consumer.handle(broker, poison, true, false);

        assert ok.status() == SendStatus.CONFIRMED && ok.routed();
        assert returned.status() == SendStatus.RETURNED && !returned.routed();
        assert unknown.status() == SendStatus.UNKNOWN;
        assert consumer.applied == 1;
        assert consumer.duplicateSkipped == 1;
        assert broker.orderQueue.ready.isEmpty();
        assert broker.deadLetterQueue.ready.size() == 1;

        System.out.println("ok=" + ok.status() + ", returned=" + returned.status() + ", timeout=" + unknown.status());
        System.out.println("applied=" + consumer.applied + ", duplicateSkipped=" + consumer.duplicateSkipped + ", dlq=" + broker.deadLetterQueue.ready.size());
    }
}
